<?php
declare(strict_types=1);
final class TaskWorkerConfig{
 public function __construct(public readonly string$workerId,public readonly int$leaseSeconds,public readonly int$sleepSeconds,public readonly int$recoveryBatch,public readonly int$recurrenceBatch=10,public readonly int$recurrenceCatchUpLimit=5,public readonly int$recurrenceRetryBatch=10,public readonly int$recurrenceOrphanSeconds=300,public readonly int$continuationBatch=3,public readonly int$replanBatch=2){}
 public static function fromEnvironment():self{$o=trim((string)getenv('TASK_WORKER_ID'));$w=$o!==''?$o:sprintf('%s:%d:%s',gethostname()?:'host',getmypid(),bin2hex(random_bytes(6)));if(strlen($w)>120)throw new InvalidArgumentException('TASK_WORKER_ID is too long');return new self($w,self::bounded('TASK_WORKER_LEASE_SECONDS',300,60,3600),self::bounded('TASK_WORKER_SLEEP_SECONDS',2,1,60),self::bounded('TASK_WORKER_RECOVERY_BATCH',50,1,200),self::bounded('TASK_WORKER_RECURRENCE_BATCH',10,1,50),self::bounded('TASK_WORKER_RECURRENCE_CATCH_UP_LIMIT',5,1,20),self::bounded('TASK_WORKER_RECURRENCE_RETRY_BATCH',10,1,50),self::bounded('TASK_WORKER_RECURRENCE_ORPHAN_SECONDS',300,30,86400),self::bounded('TASK_WORKER_CONTINUATION_BATCH',3,1,20),self::bounded('TASK_WORKER_REPLAN_BATCH',2,1,10));}
 public static function leaseToken():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-'.dechex((hexdec($h[16])&3)|8).substr($h,17,3).'-'.substr($h,20,12);}
 private static function bounded(string$k,int$d,int$min,int$max):int{$r=getenv($k);$v=$r===false||$r===''?$d:filter_var($r,FILTER_VALIDATE_INT);if($v===false||$v<$min||$v>$max)throw new InvalidArgumentException($k.' is outside the safe range');return$v;}
}
